import{calculate,validate}from'./model.mjs';
const app=document.querySelector('#app');let screen=0;const fresh=()=>({price:'950',shipping:'80',unknown:false,budget:'800',use:'',size:'unknown',policy:'unknown',store:'A',confirmed:false});let data=fresh();
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:2}).format(n/100);
const shirt=`<svg viewBox="0 0 300 300" aria-hidden="true"><path d="M103 45L62 63 20 132 72 159 90 133 86 260 215 260 210 133 229 159 281 132 240 63 196 45Q151 90 103 45Z" fill="#8fa486" stroke="#4e6b50" stroke-width="2"/><path d="M103 45Q149 109 196 45M91 133L94 85M210 133L207 85M90 247L212 247" fill="none" stroke="#66815f" stroke-width="3"/><path d="M124 54Q150 71 175 54" fill="none" stroke="#f0efde" stroke-width="3"/></svg>`;
const progress=n=>`<div class="progress"><span>Tu revisión</span>${[1,2,3].map(i=>`<i class="${i<=n?'active':''}"></i>`).join('')}<span>${n} de 3</span></div>`;
function show(n){screen=n;render();window.scrollTo(0,0);const h=app.querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}}
function render(){
if(screen===0)app.innerHTML=`<section class="hero"><div><span class="eyebrow">Un momento para ti, antes de pagar</span><h1>Que tu próxima<br>compra tenga<br><em>sentido para ti.</em></h1><p class="intro">Revisa lo que necesitas, cuánto quieres gastar y qué te falta saber. Sin presión. La decisión sigue siendo tuya.</p><button class="primary" id="start">Probar una revisión <span>↗</span></button><p class="micro">Ejercicio con una prenda ficticia. Sin registro.</p></div><div class="art">${shirt}<div class="note">¿La usaría? ¿Cabe en mi presupuesto?</div></div></section><section class="principles"><div><b><span class="num">01</span>Lo que tú necesitas</b><p>Tu uso y tus prioridades van primero.</p></div><div><b><span class="num">02</span>Los números claros</b><p>Precio, envío y presupuesto, por separado.</p></div><div><b><span class="num">03</span>Las dudas a la vista</b><p>Lo que no sabemos, no lo inventamos.</p></div></section>`;
if(screen===1)app.innerHTML=`${progress(1)}<button class="back" id="back">← Volver al inicio</button><span class="eyebrow">01 · Mira la oferta</span><h1 class="screen-title">Primero, revisa los datos.</h1><p>Usaremos esta oferta inventada. Confirma los importes antes de seguir.</p><div class="split"><div class="panel"><span class="badge">CAPTURA FICTICIA · TIENDA ${data.store}</span><div class="offer">${shirt}<span class="tag">$950 MXN</span></div><h3 style="margin:22px 0 4px">Playera de algodón</h3><p class="small">Envío: $80 MXN · Talla por confirmar</p><div class="badge">DATOS DEL EJEMPLO · LECTURA SIMULADA</div><p class="small">La página propone los datos de este ejemplo ficticio. Todavía no lee imágenes con IA ni consulta políticas reales.</p></div><form id="offerform" novalidate><div class="field"><label for="store">Tienda del ejemplo</label><select id="store"><option value="A" ${data.store==='A'?'selected':''}>Tienda A · ficticia</option><option value="B" ${data.store==='B'?'selected':''}>Tienda B · ficticia</option></select><p>Solo cambia el nombre de la tienda ficticia; la prenda, los precios y las preguntas son iguales. No es una comparación de tiendas.</p></div><div class="field"><label for="price">Precio de la prenda · MXN</label><input id="price" type="number" min="0" max="100000" step="0.01" inputmode="decimal" value="${esc(data.price)}"></div><div class="field"><label for="shipping">Envío u otros costos · MXN</label><input id="shipping" type="number" min="0" max="100000" step="0.01" inputmode="decimal" value="${esc(data.shipping)}" ${data.unknown?'disabled':''}><label class="check"><input id="unknown" type="checkbox" ${data.unknown?'checked':''}>No sé cuánto costará el envío.</label></div><label class="check"><input id="confirmed" type="checkbox" ${data.confirmed?'checked':''}>Revisé los datos del ejemplo y corregí lo necesario.</label><p id="error" class="error" role="alert" hidden></p><div class="actions"><button class="primary">Continuar <span>→</span></button></div></form></div>`;
if(screen===2)app.innerHTML=`${progress(2)}<button class="back" id="back">← Editar la oferta</button><span class="eyebrow">02 · Tus prioridades</span><h1 class="screen-title">¿Qué esperas de esta compra?</h1><p>Responde como si estuvieras probando el ejemplo. No uses información personal real.</p><div class="split"><form id="needs" novalidate><div class="field"><label for="use">¿Para qué usarías esta prenda?</label><textarea id="use" maxlength="300" placeholder="Ejemplo: para ir a clases y combinarla con mis jeans.">${esc(data.use)}</textarea><p>Una frase corta es suficiente. Puedes escribir hasta 300 letras, espacios y signos.</p></div><div class="field"><label for="budget">Presupuesto que tú eliges · MXN</label><input id="budget" type="number" min="0.01" max="100000" step="0.01" inputmode="decimal" value="${esc(data.budget)}"><p>Un límite para esta compra. No necesitamos saber tus ingresos.</p></div><div class="field"><label for="size">¿Has confirmado la talla?</label><select id="size"><option value="unknown" ${data.size==='unknown'?'selected':''}>Todavía no / no sé</option><option value="yes" ${data.size==='yes'?'selected':''}>Sí, en este ejemplo</option></select></div><div class="field"><label for="policy">¿Revisaste las condiciones de devolución?</label><select id="policy"><option value="unknown" ${data.policy==='unknown'?'selected':''}>Todavía no / no sé</option><option value="yes" ${data.policy==='yes'?'selected':''}>Sí, en este ejemplo</option></select><p>Tu respuesta no equivale a una verificación de la tienda.</p></div><p id="error" class="error" role="alert" hidden></p><button class="primary">Ver mi revisión <span>→</span></button></form><aside class="panel" style="align-self:start"><span class="eyebrow">No hay una respuesta correcta</span><h2 style="font:34px Georgia,serif">Este espacio es tuyo.</h2><p class="small">Puedes comprar, esperar o cambiar de idea. No te calificamos por tu decisión.</p><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><b class="small">¿Alguien te está ayudando?</b><p class="small">Puede explicar las preguntas, pero las respuestas deben ser tuyas. Pídele que te lea lo que escribió para confirmar que te entendió.</p></aside></div>`;
if(screen===3){const r=calculate(data);const over=r.difference>0;app.innerHTML=`${progress(3)}<button class="back" id="back">← Editar mis respuestas</button><span class="eyebrow">03 · Tu revisión</span><h1 class="screen-title">Más claridad. Tú decides.</h1><p>Esto es lo que muestran los datos que confirmaste.</p><div class="result-layout"><section><div class="card ${over?'warm':''}"><span class="eyebrow">${r.total===null?'Costo aún incompleto':over?'Sobre el límite que elegiste':'Comparación con tu presupuesto'}</span><div class="bigmoney">${r.total===null?'Falta el envío':over?money(r.difference)+' por encima':r.difference===0?'Justo en tu límite':money(-r.difference)+' disponibles'}</div><p>${r.total===null?'El precio de la prenda es '+money(r.price)+'. Sin confirmar el envío, no sabemos el total final.':over?'El total de '+money(r.total)+' supera tu presupuesto de '+money(r.budget)+'. Puedes ajustar el límite, esperar o seguir con ese costo.':'El total de '+money(r.total)+' '+(r.difference===0?'iguala':'está dentro de')+' tu presupuesto declarado. Esto no demuestra que puedas cubrir tus otros gastos.'}</p></div><div class="card"><h3>Antes de decidir, verifica</h3><ul class="list">${r.shipping===null?'<li>El costo del envío y cualquier cargo adicional.</li>':''}${data.size==='unknown'?'<li>La tabla de tallas y las medidas de la prenda.</li>':'<li>Declaraste que revisaste la talla; la demo no puede comprobar el ajuste.</li>'}<li>${data.policy==='unknown'?'Plazo, etiquetas, estado requerido, excepciones y costos de devolución.':'Declaraste que leíste la política; confirma que aplique a esa prenda y al canal de compra.'}</li></ul><p class="small"><b>Devolución: pendiente de verificación.</b> No consultamos una política real ni garantizamos que acepten devolverla.</p></div><div class="card"><span class="badge">TEXTO DE EJEMPLO · SIN IA CONECTADA</span><h3>Un siguiente paso concreto</h3><p>${data.size==='unknown'?'Busca la tabla de tallas y compárala con una prenda que ya te quede bien.':'Confirma con la tienda el plazo y las excepciones de devolución antes de pagar.'} Si la información no está clara, puedes preguntar o dejar la compra para después.</p></div></section><aside><div class="panel summary"><h3>Lo que tú elegiste</h3><b class="small">Tu motivo, tal como lo escribiste</b><p class="small" style="white-space:pre-wrap">${esc(data.use)}</p><button class="textbtn small" id="editpurpose">Corregir mi motivo</button><div class="row"><span>Prenda</span><b>${money(r.price)}</b></div><div class="row"><span>Envío / otros</span><b>${r.shipping===null?'Por confirmar':money(r.shipping)}</b></div><div class="row"><span>Total</span><b>${r.total===null?'Incompleto':money(r.total)}</b></div><div class="row"><span>Tu presupuesto</span><b>${money(r.budget)}</b></div><p class="small" style="margin-top:20px">No asignamos una calificación a tu compra. Este resumen usa solo lo que declaraste.</p><div class="actions"><button id="edit" class="secondary">Editar mis datos</button><button id="finish" class="primary">Terminar revisión ✓</button></div></div><p class="micro">No necesitas comprar ni esperar una respuesta de alguien para terminar.</p></aside></div>`;}
if(screen===4)app.innerHTML=`<section class="end"><span class="eyebrow">Revisión terminada</span><h1>La decisión<br>sigue siendo tuya.</h1><p>Terminaste el ejercicio. Borramos los datos de esta revisión de la pestaña.</p><p>No hay una compra, una solicitud de devolución ni una revisión humana en espera.</p><button id="restart" class="primary">Probar otro ejemplo <span>↗</span></button></section>`;
bind();}
function error(e){const el=document.querySelector('#error');el.hidden=false;el.textContent=e.message;el.scrollIntoView({block:'nearest'});}
function captureOffer(){data.price=document.querySelector('#price').value;data.shipping=document.querySelector('#shipping').value;data.unknown=document.querySelector('#unknown').checked;data.store=document.querySelector('#store').value;data.confirmed=document.querySelector('#confirmed').checked;}
function captureNeeds(){for(const key of['use','budget','size','policy'])data[key]=document.getElementById(key).value;}
function bind(){const on=(id,fn)=>{const el=document.getElementById(id);if(el)el.onclick=fn};on('start',()=>show(1));on('restart',()=>show(1));on('back',()=>{if(screen===1){captureOffer();show(0)}else if(screen===2){captureNeeds();show(1)}else show(2)});on('edit',()=>show(1));on('editpurpose',()=>show(2));on('finish',()=>{data=fresh();show(4)});const un=document.querySelector('#unknown');if(un)un.onchange=()=>{document.querySelector('#shipping').disabled=un.checked};const of=document.querySelector('#offerform');if(of)of.onsubmit=e=>{e.preventDefault();captureOffer();try{calculate(data);if(!data.confirmed)throw Error('Confirma que revisaste los datos del ejemplo para continuar.');show(2)}catch(e){error(e)}};const nf=document.querySelector('#needs');if(nf)nf.onsubmit=e=>{e.preventDefault();captureNeeds();try{validate(data);show(3)}catch(e){error(e)}};}
document.querySelector('#privacy').onclick=()=>document.querySelector('#info').showModal();document.querySelector('#closeinfo').onclick=()=>document.querySelector('#info').close();document.querySelector('#brand').onclick=e=>{e.preventDefault();if(screen===1)captureOffer();if(screen===2)captureNeeds();show(0)};render();
